        <span class="w-2 h-2 rounded-full shrink-0" :style="{ backgroundColor: Q9[item.district] || '#64748b' }"></span>
        <span class="text-xs font-semibold text-slate-700 truncate">{{ item.district }}</span>
        <span class="ml-auto text-xs font-bold font-mono text-slate-900 tabular-nums">{{ item.units.toLocaleString() }}</span>
        <span class="text-[11px] font-mono text-slate-500 w-10 text-right tabular-nums shrink-0">({{ pct(item) }}%)</span>
      </div>
    </div>
  </div>
</template>

<script>
import { Z9, Q9 } from '../assets/data.js'

export default {
  name: 'DistrictPie',
  props: {
    dataPoints: { type: Array, default: () => [] }
  },
  data() {
    return { Q9 }
  },
  computed: {
    total() {
      return this.dataPoints.reduce((sum, item) => sum + item.units, 0)
    },
    sorted() {
      return [...this.dataPoints].sort(
        (a, b) => Z9.indexOf(a.district) - Z9.indexOf(b.district)
      )
    },
    cols() {
      return [this.sorted.slice(0, 5), this.sorted.slice(5, 10)]
    }
  },
  methods: {
    pct(item) {
      return this.total > 0 ? (item.units / this.total * 100).toFixed(0) : '0'
    }
  }
}
</script>

"}]

