const fs = require('fs');
const p = 'zhi2-web-admin/src/views/property/marketMonitor/components/KpiCards.vue';
let s = fs.readFileSync(p, 'utf8');

// Replace template expressions: 环比 {{ X >= 0 ? '+' : '' }}{{ EXPR }}%
// -> 环比 {{ fmtPct(EXPR) }}
// We match the pattern generically.
const re = /环比 \{\{ [\w.$?[\]()!>=< ]+ \? '\+' : '' \}\}\{\{ ([\w.$?\[\]()!>=< ??]+?) \}\}%/g;
let count = 0;
s = s.replace(re, (m, expr) => { count++; return `环比 {{ fmtPct(${expr.trim()}) }}`; });
console.log('replaced', count, 'occurrences');

if (!/methods\s*:/.test(s)) {
  // insert methods before final closing of export default object: replace "  }\n}\n</script>"
  // find the end of computed block: "  }\n}\n</script>"
  const idx = s.lastIndexOf('  }\n}\n</script>');
  if (idx >= 0) {
    s = s.slice(0, idx) + `  },
  methods: {
    fmtPct(v) {
      const n = Number(v);
      if (!isFinite(n)) return '0.00'
      const fixed = n.toFixed(2)
      return (n >= 0 ? '+' : '') + fixed
    }
  }
}
</script>` + s.slice(idx + '  }\n}\n</script>'.length);
    console.log('inserted methods block');
  } else {
    console.log('WARN: could not find insertion point');
  }
}
fs.writeFileSync(p, s);

