const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newContext({ viewport: { width: 1920, height: 1080 } }).then(c => c.newPage());
  await page.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  // select 姑苏 in 监测范围 select (2nd select in header)
  const selects = page.locator('.mm-dashboard header select');
  const n = await selects.count();
  // find the one with option 姑苏
  let done = false;
  for (let i = 0; i < n; i++) {
    const opts = await selects.nth(i).locator('option').allTextContents();
    if (opts.some(o => o.includes('姑苏'))) {
      const val = await selects.nth(i).locator('option', { hasText: '姑苏' }).first().getAttribute('value');
      await selects.nth(i).selectOption(val);
      done = true;
      break;
    }
  }
  await page.waitForTimeout(1000);
  // read all 环比 texts
  const mom = await page.locator('.mm-dashboard').innerText();
  const matches = mom.match(/环比\s*[+-]?\d+(\.\d+)?%/g) || [];
  console.log('selected:', done);
  console.log('环比 samples:', JSON.stringify(matches));
  const bad = matches.filter(m => {
    const num = m.replace('环比','').replace('%','').trim();
    return /\.\d{3,}/.test(num);
  });
  console.log('long-tail ones:', JSON.stringify(bad));
  await page.screenshot({ path: '.workbuddy/kpi-gusu.png', clip: { x: 0, y: 60, width: 1920, height: 200 } });
  await browser.close();
})();

