const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newContext({ viewport: { width: 1920, height: 1080 } }).then(c => c.newPage());
  const errs = [];
  page.on('pageerror', e => errs.push('PE:' + e.message));
  page.on('console', m => { if (['error','warning'].includes(m.type())) errs.push(m.type().toUpperCase() + ':' + m.text()); });
  page.on('requestfailed', r => errs.push('REQFAIL:' + r.url()));
  await page.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'domcontentloaded' });
  await page.waitForSelector('.mm-dashboard', { timeout: 20000 });
  await page.waitForTimeout(2500);
  // check for message box
  const boxes = await page.locator('.el-message-box__wrapper:visible, .el-message:visible').allTextContents().catch(() => []);
  console.log('visible message boxes:', JSON.stringify(boxes));
  console.log('errors:', JSON.stringify(errs.slice(0, 12), null, 2));
  await page.screenshot({ path: '.workbuddy/dialog-state.png' });
  await browser.close();
})();

